-- VITARA: 52 Verified Cultural Dishes Seed (FIXED)
-- Fix for ERROR 428C9: gl_score is a GENERATED column, and glycemic_tier is generated from it.
-- Both columns were removed from the INSERT list and from every VALUES tuple (2 values per row).
-- Postgres now computes them: gl_score = round(gi_estimate * (carbs_g - fiber_g) / 100),
-- glycemic_tier = low (gl <= 10) / medium (11-19) / high (>= 20).
-- All 52 supplied gl/tier values matched that formula, so no data is lost.

INSERT INTO public.cultural_foods (
  dish_name, culture, meal_slot, dietary_pattern, serving_description, serving_grams,
  calories, protein_g, carbs_g, fiber_g, fat_g, gi_estimate,
