) VALUES
-- 1-18: South Asian Lacto-Vegetarian
('Moong Dal Tadka + 1 Whole Wheat Roti + Bhindi Sabzi', 'North Indian', ARRAY['lunch','dinner'], 'lacto_vegetarian', '180g dal + 40g roti + 100g okra', 320, 410, 16, 54, 11, 13, 42, 'Eat the soluble-fiber bhindi and protein-rich moong dal first before the roti to cut glucose spike by ~30%.', 'sa_lunch_plate'),
('Palak Paneer + 1 Missi Roti (Besan-Wheat)', 'North Indian', ARRAY['lunch','dinner'], 'lacto_vegetarian', '180g palak paneer + 45g missi roti', 225, 445, 22, 29, 8, 26, 35, 'Blending chickpea flour (besan) into wheat dough drops the roti GI from 62 to 45.', 'sa_dinner_plate'),
